+
+    private GovernorPost(UUID id, Type type, BlockPos pos, int number, @Nullable UUID assigned) {
+        this.id = id;
+        this.type = type;
+        this.pos = pos.immutable();
+        this.number = number;
+        this.assigned = assigned;
